// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ACCURAL_DEPOSIT} from "../src/ACCURAL_DEPOSIT.sol";

contract InvMutTest is Test {
    ACCURAL_DEPOSIT c;
    function setUp() public { c = new ACCURAL_DEPOSIT(); }
    function testFuzz_property(address caller, uint256 newMin) public {
        vm.assume(caller != address(0));

        c.Initialized();

        bool ok;
        vm.prank(caller);
        try c.SetMinSum(newMin) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(!ok);
    }
}
